16	func (s *APIV1Service) SetMemoAttachments(ctx context.Context, request *v1pb.SetMemoAttachmentsRequest) (*emptypb.Empty, error) {
17		user, err := s.fetchCurrentUser(ctx)
18		if err != nil {
19			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
20		}
21		if user == nil {
22			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
23		}
24		memoUID, err := ExtractMemoUIDFromName(request.Name)
25		if err != nil {
26			return nil, status.Errorf(codes.InvalidArgument, "invalid memo name: %v", err)
27		}
28		memo, err := s.Store.GetMemo(ctx, &store.FindMemo{UID: &memoUID})
29		if err != nil {
30			return nil, status.Errorf(codes.Internal, "failed to get memo")
31		}
32		if memo == nil {
33			return nil, status.Errorf(codes.NotFound, "memo not found")
34		}
35		if !canModifyMemo(user, memo) {
36			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
37		}
38		if err := s.setMemoAttachmentsInternal(ctx, user, memo, request.Attachments); err != nil {
39			return nil, err
40		}
41		if err := s.touchMemoUpdatedTimestamp(ctx, memo.ID); err != nil {
42			return nil, err
43		}
44		updatedMemo, parentMemo, memoMessage, err := s.buildUpdatedMemoState(ctx, memo.ID)
45		if err != nil {
46			return nil, status.Errorf(codes.Internal, "failed to build updated memo state")
47		}
48		s.dispatchMemoUpdatedSideEffects(ctx, updatedMemo, parentMemo, memoMessage)
49	
50		return &emptypb.Empty{}, nil
51	}
